  "discussion": { text: "discussion", type: "noun", definition: "a conversation or debate in which ideas and opinions are exchanged; a detailed treatment of a topic", context: "The discussion highlighted multifaceted dimensions of how digital platforms have fundamentally restructured contemporary communication patterns." },
"social_media": {
  text: "social media",
  type: "noun",
  definition: "websites and apps that allow people to create, share, and interact with content and communicate with others online",
  context: "Many people now get their news primarily through social media rather than traditional newspapers or TV."},

  "basically": { text: "basically", type: "adverb", definition: "in essence; fundamentally; at the most basic level", context: "Social media has basically become the primary conduit through which information disseminates across contemporary societies." },
  "main": { text: "main", type: "adjective", definition: "principal; of primary importance or significance", context: "The main contention in contemporary media studies is whether social platforms enhance or undermine civic engagement." },
