  "made": { text: "made", type: "verb", definition: "past tense of make; caused something to exist or brought about a particular result", context: "The documentary made a compelling argument about the systemic inequalities inherent in the institution." },
  "realize": { text: "realize", type: "verb", definition: "to become aware of or understand something; to make something actual or concrete", context: "Only after extensive research did she realize the profound implications of the theoretical framework." },
  "barely": { text: "barely", type: "adverb", definition: "only just; almost not; by the narrowest margin", context: "The manuscript was barely legible, having deteriorated considerably over the centuries." },
  "check": { text: "check", type: "verb", definition: "to verify or examine something to ensure accuracy, safety, or proper functioning", context: "Before submitting the research paper, I meticulously checked all citations against the original sources." },
  "traditional": { text: "traditional", type: "adjective", definition: "established by long-standing custom or practice; conforming to conventional patterns", context: "While traditional methodologies have merit, contemporary researchers increasingly advocate for interdisciplinary approaches." },
  "sites": { text: "sites", type: "noun", definition: "plural of site; locations or positions where something is situated or occurs", context: "Archaeological sites in the region revealed artefacts spanning multiple civilizations and millennia." },
  "anymore": { text: "anymore", type: "adverb", definition: "any longer; no longer; at the present time (typically used in negative contexts)", context: "She doesn't visit that establishment anymore, having found alternative venues more conducive to her research." },
  "unless": { text: "unless", type: "conjunction", definition: "except if; in the case that not; introducing a condition that must not occur", context: "Unless compelling evidence emerges to contradict the hypothesis, we shall proceed with implementation of the proposed framework." },
  "happens": { text: "happens", type: "verb", definition: "occurs or takes place; comes to pass as an event or circumstance", context: "Whenever systemic disruption happens within complex organizations, the ramifications typically cascade unpredictably." },
