  "finds": { text: "finds", type: "verb", definition: "discovers or locates something; comes across by chance or search", context: "The study finds a significant correlation between environmental policies and long-term economic sustainability." },
  "pick": { text: "pick", type: "verb", definition: "to choose or select; to lift or remove something with fingers", context: "The committee will pick the most qualified candidate based on demonstrated expertise and experience." },
  "phone": { text: "phone", type: "noun", definition: "a device for transmitting and receiving sound over distance; a telecommunications instrument", context: "The anthropologist argued that smartphone usage has fundamentally altered communication patterns in modern societies." },
  "reply": { text: "reply", type: "verb", definition: "to respond or answer; to say or write something in response", context: "The spokesperson declined to reply to inquiries regarding the organization's financial discrepancies." },
  "message": { text: "message", type: "noun", definition: "a piece of information or communication transmitted from one party to another, often containing a specific meaning or intention", context: "The underlying message of the novel concerns the dangers of unchecked technological advancement." },
  "reading": { text: "reading", type: "verb", definition: "the act of interpreting written or printed text; to engage with and understand written material", context: "She is reading a comprehensive analysis of postcolonial theory." },
  "happened": { text: "happened", type: "verb", definition: "to occur or take place; to come about as an event or circumstance", context: "The paradigm shift happened gradually, as scholars began to challenge established assumptions." },
  "world": { text: "world", type: "noun", definition: "the earth and all of its inhabitants; the sphere of human life and activity; a particular realm or domain", context: "The geopolitical landscape of the modern world is characterized by unprecedented complexity." },
  "kind": { text: "kind", type: "adjective", definition: "having a gentle, caring, or considerate nature; benevolent and compassionate", context: "The mentor was kind in her critique, offering constructive feedback alongside recognition of merit." },
  "crazy": { text: "crazy", type: "adjective", definition: "extremely surprising, shocking, or remarkable; seemingly irrational or absurd", context: "It's crazy how rapidly misinformation can propagate across social media platforms." },
  "post": { text: "post", type: "verb", definition: "to publish or share content on a digital platform or display something publicly", context: "She decided to post her research findings on the academic social network." },
  "suddenly": { text: "suddenly", type: "adverb", definition: "occurring or done unexpectedly and without warning; abruptly", context: "The narrative suddenly shifted when credible sources contradicted the initial reports." },
  "everyone's": { text: "everyone's", type: "pronoun", definition: "belonging to or affecting all people; possessive form of 'everyone'", context: "Everyone's scrutinizing the authenticity of the leaked documents." },
  "spreads": { text: "spreads", type: "verb", definition: "to extend over a wider area; to disseminate or transmit widely", context: "Conspiracy theories spread exponentially through algorithmically-curated feeds." },
  "wildfire": { text: "wildfire", type: "noun", definition: "an uncontrolled fire spreading rapidly through vegetation; used metaphorically for something spreading uncontrollably", context: "False narratives propagate like wildfire, overwhelming fact-checking mechanisms." },
  "doesn't": { text: "doesn't", type: "verb", definition: "does not; negative form of 'does'", context: "The platform doesn't adequately moderate content for accuracy." },
  "media": { text: "media", type: "noun", definition: "plural of medium; channels of communication and information dissemination", context: "Traditional media outlets face competition from unregulated digital media platforms." },
