  "accessible": { text: "accessible", type: "adjective", definition: "capable of being reached, entered, or approached; easy to understand or obtain", context: "The director's latest film makes complex existential themes accessible to a broader audience." },
  "ago": { text: "ago", type: "adverb", definition: "in the past; at a time previous to the present", context: "The geopolitical landscape has transformed dramatically since the regime collapsed twenty years ago." },
  "political": { text: "political", type: "adjective", definition: "relating to the governance, organization, or public affairs of a state or community", context: "The documentary examined the political ramifications of decolonization movements throughout the twentieth century." },
  "end": { text: "end", type: "noun/verb", definition: "the final part or termination of something; to bring something to a conclusion", context: "The author deliberately subverted narrative convention by ending the novel abruptly, leaving moral ambiguity unresolved." },
  "three": { text: "three", type: "noun", definition: "the number 3", context: "The committee comprised three distinguished scholars whose expertise spanned medieval history, philosophy, and linguistics." },
  "four": { text: "four", type: "noun", definition: "the number 4", context: "The manuscript's four chapters systematically deconstruct foundational assumptions in contemporary epistemology." },
  "articles": { text: "articles", type: "noun", definition: "pieces of writing on a particular subject in a newspaper, magazine, or journal; written compositions", context: "The researcher synthesized insights from hundreds of peer-reviewed articles spanning multiple disciplines." },
  "piece": { text: "piece", type: "noun", definition: "a single item or part of something; a work of art or creative composition", context: "This masterwork represents the artist's most ambitious piece, integrating Byzantine iconography with modernist abstraction." },
  "everything": { text: "everything", type: "pronoun", definition: "all things; the totality of relevant matters or concerns", context: "The pandemic has fundamentally transformed everything about how we conceptualize work and community engagement." },
  "together": { text: "together", type: "adverb", definition: "with or in combination with another person or thing; simultaneously or as a unit", context: "The researchers worked together to synthesize their findings into a comprehensive theoretical framework." },
  "two-minute": { text: "two-minute", type: "adjective", definition: "lasting or allocated for a duration of two minutes", context: "The two-minute discourse was insufficient to adequately address the multifaceted implications of the proposal." },
  "explains": { text: "explains", type: "verb", definition: "to make clear, intelligible, or comprehensible; to provide an account or justification for", context: "The researcher explains the causal mechanisms linking socioeconomic deprivation to adverse health outcomes with remarkable clarity." },
  "whole": { text: "whole", type: "adjective/noun", definition: "complete, entire, or undivided; the totality of something considered as a unified entity", context: "Rather than fragmenting the analysis, we should examine the whole ecosystem to understand the intricate interdependencies at play." },
  "surprisingly": { text: "surprisingly", type: "adverb", definition: "in a manner that astonishes or causes surprise; contrary to what was expected", context: "Surprisingly, the data demonstrated a counterintuitive inverse correlation between educational attainment and certain measures of subjective well-being." },
  "firsthand": { text: "firsthand", type: "adjective", definition: "obtained or experienced directly and personally; from immediate observation rather than from hearsay", context: "Having conducted fieldwork extensively, the anthropologist provided firsthand testimony regarding the cultural practices previously documented only through secondary sources." },
  "posts": { text: "posts", type: "noun/verb", definition: "messages or content published on social media or online platforms; to publish or display content online", context: "The social media posts revealed how rapidly misinformation propagates through algorithmic echo chambers, distorting public discourse." },
  "genuine": { text: "genuine", type: "adjective", definition: "authentic, sincere, or true; not counterfeit, artificial, or pretended", context: "The memoir's genuine emotional resonance derives from its unflinching examination of the author's psychological vulnerabilities and moral ambiguities." },
  "anything": { text: "anything", type: "pronoun", definition: "any thing, fact, or consideration; used to refer to something unspecified or of any kind", context: "The postmodern theorist argued that meaning is more indeterminate and contingent than anything modernist aesthetics had previously acknowledged." },
  "outlet": { text: "outlet", type: "noun", definition: "a store or shop that sells goods at reduced prices, or a means of expressing emotions or ideas", context: "The independent news outlet provided an alternative perspective to mainstream media coverage." },
  "publishes": { text: "publishes", type: "verb", definition: "to make publicly known or to issue a book, journal, or article for distribution", context: "The academic researcher publishes her findings in peer-reviewed journals annually." },
  "protest": { text: "protest", type: "noun", definition: "a demonstration or expression of objection against something considered unjust or wrong", context: "The peaceful protest drew thousands of citizens advocating for systemic reform." },
  "uploading": { text: "uploading", type: "verb", definition: "transferring or transmitting data from a local device to a remote server or platform", context: "The content creators were uploading high-resolution documentation to multiple platforms simultaneously." },
