  "properly": { text: "properly", type: "adverb", definition: "in a correct, appropriate, or suitable manner; following accepted standards or procedures", context: "The investigation was not conducted properly, which subsequently undermined the credibility of the findings." },
  "messy": { text: "messy", type: "adjective", definition: "characterized by disorder, disarray, or lack of clarity", context: "The political situation became increasingly messy as various factions pursued conflicting agendas." },
